-- NAMAA Finance schema baseline (v0.7.0 database rebase, Milestone 7).
-- Generated by replaying the complete development migration chain
-- 0001_initial..0024_dashboard_snapshot_audit (preserved at git tags
-- pre-ui-redesign-v0.6.0 and pre-db-rebase-v0.6.7) and dumping the
-- resulting schema verbatim. Development databases created before this
-- rebase are incompatible and must be deleted and recreated.
-- Schema version stays 24: this file recreates that exact schema.

-- ── tables ──
CREATE TABLE clients (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  company TEXT,
  address TEXT,
  phone TEXT,
  email TEXT,
  tax_number TEXT,
  contacts TEXT, -- JSON [{name, role, phone, email}]
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT);
CREATE TABLE expense_categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name_en TEXT NOT NULL,
  name_ar TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 0
, sync_uuid TEXT, updated_at TEXT);
CREATE TABLE people (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL DEFAULT 'FREELANCER' CHECK (type IN ('EMPLOYEE','FREELANCER')),
  name TEXT NOT NULL,
  specialization TEXT,
  phone TEXT,
  email TEXT,
  bank_account TEXT,
  hourly_rate_minor INTEGER CHECK (hourly_rate_minor IS NULL OR hourly_rate_minor >= 0),
  monthly_rate_minor INTEGER CHECK (monthly_rate_minor IS NULL OR monthly_rate_minor >= 0),
  currency TEXT NOT NULL DEFAULT 'EGP',
  notes TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT);
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE currencies (
  code TEXT PRIMARY KEY,
  fx_rate_micro INTEGER NOT NULL CHECK (fx_rate_micro > 0),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE backups_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  path TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'MANUAL' CHECK (kind IN ('AUTO','MANUAL')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, filename TEXT, database_version INTEGER, application_version TEXT, sha256_checksum TEXT, backup_type TEXT, source_device TEXT);
CREATE TABLE "projects" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  client_id INTEGER NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  country TEXT,
  city TEXT,
  manager TEXT,
  discipline TEXT NOT NULL DEFAULT 'MULTI',
  project_type TEXT,
  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (status IN ('ACTIVE','ON_HOLD','COMPLETED','CANCELLED')),
  currency TEXT NOT NULL DEFAULT 'EGP',
  fx_rate_micro INTEGER NOT NULL DEFAULT 1000000 CHECK (fx_rate_micro > 0),
  start_date TEXT,
  end_date TEXT,
  progress_bp INTEGER NOT NULL DEFAULT 0 CHECK (progress_bp BETWEEN 0 AND 10000),
  description TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT);
CREATE TABLE "contracts" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES "projects"(id) ON DELETE CASCADE,
  number TEXT NOT NULL,
  title TEXT,
  value_minor INTEGER NOT NULL DEFAULT 0 CHECK (value_minor >= 0),
  vat_bp INTEGER NOT NULL DEFAULT 1400 CHECK (vat_bp BETWEEN 0 AND 10000),
  retention_bp INTEGER NOT NULL DEFAULT 0 CHECK (retention_bp BETWEEN 0 AND 10000),
  withholding_bp INTEGER NOT NULL DEFAULT 0 CHECK (withholding_bp BETWEEN 0 AND 10000),
  advance_minor INTEGER NOT NULL DEFAULT 0 CHECK (advance_minor >= 0),
  advance_recovery_method TEXT NOT NULL DEFAULT 'PROPORTIONAL'
    CHECK (advance_recovery_method IN ('PROPORTIONAL','MANUAL')),
  performance_bond_bp INTEGER NOT NULL DEFAULT 0 CHECK (performance_bond_bp BETWEEN 0 AND 10000),
  performance_bond_bank TEXT,
  performance_bond_expiry TEXT,
  payment_terms_days INTEGER NOT NULL DEFAULT 30 CHECK (payment_terms_days BETWEEN 0 AND 3650),
  payment_terms_notes TEXT,
  valuation_mode TEXT NOT NULL DEFAULT 'LUMP_SUM'
    CHECK (valuation_mode IN ('LUMP_SUM','MILESTONES','DRAWINGS')),
  milestones TEXT,
  drawings TEXT,
  attachments TEXT,
  signed_date TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT);
CREATE TABLE "payment_certificates" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  contract_id INTEGER NOT NULL REFERENCES "contracts"(id) ON DELETE CASCADE,
  seq INTEGER NOT NULL,
  number TEXT NOT NULL,
  date TEXT NOT NULL,
  submission_date TEXT,
  due_date_override TEXT,
  description TEXT,
  gross_minor INTEGER NOT NULL DEFAULT 0 CHECK (gross_minor >= 0),
  discount_minor INTEGER NOT NULL DEFAULT 0 CHECK (discount_minor >= 0 AND discount_minor <= gross_minor),
  manual_advance_recovery_minor INTEGER CHECK (manual_advance_recovery_minor IS NULL OR manual_advance_recovery_minor >= 0),
  status TEXT NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT','SUBMITTED','APPROVED','PAID')),
  deleted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT, voided_at TEXT, voided_by TEXT, void_reason TEXT, reversal_of_id INTEGER REFERENCES payment_certificates(id) ON DELETE RESTRICT, contract_revision_id INTEGER REFERENCES contract_revisions(id) ON DELETE RESTRICT, contract_value_minor_snapshot INTEGER, vat_bp_snapshot INTEGER, retention_bp_snapshot INTEGER, withholding_bp_snapshot INTEGER, advance_minor_snapshot INTEGER, advance_method_snapshot TEXT, payment_terms_days_snapshot INTEGER, currency_snapshot TEXT, fx_rate_micro_snapshot INTEGER, due_date_confirmed_at TEXT);
CREATE TABLE "payments" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  contract_id INTEGER NOT NULL REFERENCES "contracts"(id) ON DELETE CASCADE,
  kind TEXT NOT NULL DEFAULT 'CERTIFICATE'
    CHECK (kind IN ('CERTIFICATE','ADVANCE','RETENTION_RELEASE')),
  number TEXT NOT NULL,
  date TEXT NOT NULL,
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  method TEXT NOT NULL DEFAULT 'BANK_TRANSFER'
    CHECK (method IN ('BANK_TRANSFER','CHEQUE','CASH')),
  bank TEXT,
  reference TEXT,
  notes TEXT,
  deleted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, voided_at TEXT, voided_by TEXT, void_reason TEXT, reversal_of_id INTEGER REFERENCES payments(id) ON DELETE RESTRICT);
CREATE TABLE "payment_certificate_allocations" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  payment_id INTEGER NOT NULL REFERENCES "payments"(id) ON DELETE CASCADE,
  certificate_id INTEGER NOT NULL REFERENCES "payment_certificates"(id) ON DELETE CASCADE,
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0)
, sync_uuid TEXT, updated_at TEXT, integrity_exception INTEGER NOT NULL DEFAULT 0
  CHECK (integrity_exception IN (0,1)));
CREATE TABLE "project_assignments" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  person_id INTEGER NOT NULL REFERENCES people(id) ON DELETE CASCADE,
  project_id INTEGER NOT NULL REFERENCES "projects"(id) ON DELETE CASCADE,
  agreed_minor INTEGER NOT NULL DEFAULT 0 CHECK (agreed_minor >= 0),
  currency TEXT NOT NULL DEFAULT 'EGP',
  fx_rate_micro INTEGER NOT NULL DEFAULT 1000000 CHECK (fx_rate_micro > 0),
  scope TEXT,
  progress_note TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT);
CREATE TABLE "person_payments" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  assignment_id INTEGER NOT NULL REFERENCES "project_assignments"(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, voided_at TEXT, voided_by TEXT, void_reason TEXT, reversal_of_id INTEGER REFERENCES person_payments(id) ON DELETE RESTRICT);
CREATE TABLE "expenses" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  date TEXT NOT NULL,
  category_id INTEGER NOT NULL REFERENCES expense_categories(id) ON DELETE RESTRICT,
  description TEXT NOT NULL,
  project_id INTEGER REFERENCES "projects"(id) ON DELETE CASCADE,
  supplier TEXT,
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  currency TEXT NOT NULL DEFAULT 'EGP',
  fx_rate_micro INTEGER NOT NULL DEFAULT 1000000 CHECK (fx_rate_micro > 0),
  attachment_path TEXT,
  person_payment_id INTEGER REFERENCES "person_payments"(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT, archived_at TEXT, archived_by TEXT, archive_reason TEXT, voided_at TEXT, voided_by TEXT, void_reason TEXT, reversal_of_id INTEGER REFERENCES expenses(id) ON DELETE RESTRICT, number TEXT);
CREATE TABLE project_stages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  start_date TEXT,
  end_date TEXT,
  status TEXT NOT NULL DEFAULT 'PLANNED'
    CHECK (status IN ('PLANNED','IN_PROGRESS','COMPLETED','ON_HOLD')),
  completion_bp INTEGER NOT NULL DEFAULT 0 CHECK (completion_bp BETWEEN 0 AND 10000),
  engineers TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT);
CREATE TABLE recurring_expenses (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category_id INTEGER NOT NULL REFERENCES expense_categories(id) ON DELETE RESTRICT,
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  currency TEXT NOT NULL DEFAULT 'EGP',
  fx_rate_micro INTEGER NOT NULL DEFAULT 1000000 CHECK (fx_rate_micro > 0),
  day_of_month INTEGER NOT NULL DEFAULT 1 CHECK (day_of_month BETWEEN 1 AND 31),
  is_active INTEGER NOT NULL DEFAULT 1,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sync_uuid TEXT, updated_at TEXT);
CREATE TABLE sync_tombstones (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tbl TEXT NOT NULL,
  row_uuid TEXT NOT NULL,
  deleted_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE sync_state (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE time_entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  person_id INTEGER NOT NULL REFERENCES people(id) ON DELETE CASCADE,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  stage_id INTEGER REFERENCES project_stages(id) ON DELETE SET NULL,
  date TEXT NOT NULL,
  minutes INTEGER NOT NULL CHECK (minutes > 0),
  billable INTEGER NOT NULL DEFAULT 1,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  sync_uuid TEXT,
  updated_at TEXT
);
CREATE TABLE contract_revisions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  contract_id INTEGER NOT NULL REFERENCES contracts(id) ON DELETE RESTRICT,
  revision_number INTEGER NOT NULL CHECK (revision_number > 0),
  effective_date TEXT NOT NULL,
  contract_value_minor INTEGER NOT NULL CHECK (contract_value_minor >= 0),
  vat_bp INTEGER NOT NULL CHECK (vat_bp BETWEEN 0 AND 10000),
  retention_bp INTEGER NOT NULL CHECK (retention_bp BETWEEN 0 AND 10000),
  withholding_bp INTEGER NOT NULL CHECK (withholding_bp BETWEEN 0 AND 10000),
  advance_minor INTEGER NOT NULL CHECK (advance_minor >= 0),
  advance_recovery_method TEXT NOT NULL CHECK (advance_recovery_method IN ('PROPORTIONAL','MANUAL')),
  payment_terms_days INTEGER NOT NULL CHECK (payment_terms_days BETWEEN 0 AND 3650),
  currency TEXT NOT NULL,
  fx_rate_micro INTEGER NOT NULL CHECK (fx_rate_micro > 0),
  reason TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_by TEXT,
  approved_at TEXT,
  sync_uuid TEXT,
  updated_at TEXT,
  UNIQUE(contract_id, revision_number)
);
CREATE TABLE variation_orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  contract_id INTEGER NOT NULL REFERENCES contracts(id) ON DELETE RESTRICT,
  revision_id INTEGER NOT NULL REFERENCES contract_revisions(id) ON DELETE RESTRICT,
  number TEXT NOT NULL,
  description TEXT,
  value_delta_minor INTEGER NOT NULL,
  approved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_by TEXT,
  sync_uuid TEXT,
  updated_at TEXT,
  UNIQUE(contract_id, number)
);
CREATE TABLE audit_logs(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 timestamp TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 user_id TEXT, device_id TEXT NOT NULL, action TEXT NOT NULL,
 entity_type TEXT NOT NULL, entity_id INTEGER, entity_uuid TEXT,
 before_json TEXT, after_json TEXT, reason TEXT,
 source TEXT NOT NULL DEFAULT 'DESKTOP', application_version TEXT NOT NULL DEFAULT '0.6.0'
, finalized INTEGER NOT NULL DEFAULT 0 CHECK(finalized IN(0,1)));
CREATE TABLE audit_context(
  id INTEGER PRIMARY KEY CHECK(id=1),
  source TEXT NOT NULL DEFAULT 'DESKTOP',
  application_version TEXT NOT NULL DEFAULT '0.6.3'
);
CREATE TABLE app_metadata(
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE data_quality_issues(
 id INTEGER PRIMARY KEY,
 entity_type TEXT NOT NULL,
 entity_id INTEGER NOT NULL,
 field_name TEXT NOT NULL,
 issue_code TEXT NOT NULL,
 raw_value TEXT,
 detected_at TEXT NOT NULL DEFAULT(datetime('now')),
 resolved_at TEXT,
 resolution_note TEXT
);
CREATE TABLE "documents"(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
 category TEXT NOT NULL DEFAULT 'OTHER' CHECK(category IN('CONTRACT','BOQ','PROPOSAL','INVOICE','DRAWING','OTHER')),
 title TEXT NOT NULL,
 path TEXT,
 added_at TEXT NOT NULL DEFAULT(datetime('now')),
 sync_uuid TEXT,
 updated_at TEXT,
 document_uuid TEXT NOT NULL,
 original_filename TEXT NOT NULL,
 extension TEXT,
 mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',
 size_bytes INTEGER CHECK(size_bytes IS NULL OR size_bytes>=0),
 sha256 TEXT CHECK(sha256 IS NULL OR length(sha256)=64),
 storage_provider TEXT NOT NULL DEFAULT 'LOCAL_ONLY' CHECK(storage_provider IN('LOCAL_ONLY','SUPABASE','LEGACY_LOCAL')),
 cloud_storage_key TEXT,
 local_cache_path TEXT,
 version_number INTEGER NOT NULL DEFAULT 1 CHECK(version_number>0),
 uploaded_at TEXT,
 uploaded_by TEXT,
 is_available_offline INTEGER NOT NULL DEFAULT 0 CHECK(is_available_offline IN(0,1)),
 archived_at TEXT,
 UNIQUE(document_uuid,version_number)
);
CREATE TABLE document_cache(
 document_id INTEGER PRIMARY KEY REFERENCES documents(id) ON DELETE CASCADE,
 local_cache_path TEXT NOT NULL,
 is_available_offline INTEGER NOT NULL DEFAULT 1 CHECK(is_available_offline IN(0,1)),
 verified_at TEXT
);
CREATE TABLE sync_record_state(
 table_name TEXT NOT NULL,
 row_uuid TEXT NOT NULL,
 payload_json TEXT NOT NULL,
 remote_updated_at TEXT NOT NULL,
 synced_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 PRIMARY KEY(table_name,row_uuid)
);
CREATE TABLE sync_conflicts(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 table_name TEXT NOT NULL,
 row_uuid TEXT NOT NULL,
 conflict_kind TEXT NOT NULL CHECK(conflict_kind IN ('CONCURRENT_EDIT','DELETE_VS_EDIT','DUPLICATE_RECORD')),
 local_json TEXT,
 remote_json TEXT,
 local_updated_at TEXT,
 remote_updated_at TEXT,
 status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','RESOLVED')),
 resolution TEXT CHECK(resolution IN ('KEEP_LOCAL','KEEP_REMOTE')),
 resolution_note TEXT,
 detected_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 resolved_at TEXT,
 resolved_by TEXT
);
CREATE TABLE numbering_sequences(
 sequence_type TEXT NOT NULL CHECK(sequence_type IN ('PROJECT','CONTRACT','CERTIFICATE','PAYMENT','EXPENSE')),
 year INTEGER NOT NULL CHECK(year BETWEEN 2000 AND 9999),
 prefix TEXT NOT NULL CHECK(length(prefix) BETWEEN 1 AND 12),
 last_number INTEGER NOT NULL DEFAULT 0 CHECK(last_number >= 0),
 PRIMARY KEY(sequence_type,year,prefix)
);

-- ── indexes ──
CREATE INDEX idx_projects_client ON projects(client_id);
CREATE INDEX idx_projects_status ON projects(status);
CREATE INDEX idx_contracts_project ON contracts(project_id);
CREATE INDEX idx_certificates_contract ON payment_certificates(contract_id);
CREATE INDEX idx_certificates_status ON payment_certificates(status);
CREATE INDEX idx_payments_contract ON payments(contract_id);
CREATE INDEX idx_allocations_payment ON payment_certificate_allocations(payment_id);
CREATE INDEX idx_allocations_certificate ON payment_certificate_allocations(certificate_id);
CREATE INDEX idx_expenses_project ON expenses(project_id);
CREATE INDEX idx_expenses_category ON expenses(category_id);
CREATE INDEX idx_expenses_date ON expenses(date);
CREATE INDEX idx_expenses_person_payment ON expenses(person_payment_id);
CREATE INDEX idx_assignments_person ON project_assignments(person_id);
CREATE INDEX idx_assignments_project ON project_assignments(project_id);
CREATE INDEX idx_person_payments_assignment ON person_payments(assignment_id);
CREATE INDEX idx_stages_project ON project_stages(project_id);
CREATE INDEX idx_tombstones_tbl ON sync_tombstones(tbl, deleted_at);
CREATE UNIQUE INDEX idx_clients_sync_uuid ON clients(sync_uuid);
CREATE UNIQUE INDEX idx_projects_sync_uuid ON projects(sync_uuid);
CREATE UNIQUE INDEX idx_contracts_sync_uuid ON contracts(sync_uuid);
CREATE UNIQUE INDEX idx_payment_certificates_sync_uuid ON payment_certificates(sync_uuid);
CREATE UNIQUE INDEX idx_payments_sync_uuid ON payments(sync_uuid);
CREATE UNIQUE INDEX idx_payment_certificate_allocations_sync_uuid ON payment_certificate_allocations(sync_uuid);
CREATE UNIQUE INDEX idx_expense_categories_sync_uuid ON expense_categories(sync_uuid);
CREATE UNIQUE INDEX idx_expenses_sync_uuid ON expenses(sync_uuid);
CREATE UNIQUE INDEX idx_people_sync_uuid ON people(sync_uuid);
CREATE UNIQUE INDEX idx_project_assignments_sync_uuid ON project_assignments(sync_uuid);
CREATE UNIQUE INDEX idx_person_payments_sync_uuid ON person_payments(sync_uuid);
CREATE UNIQUE INDEX idx_project_stages_sync_uuid ON project_stages(sync_uuid);
CREATE UNIQUE INDEX idx_recurring_expenses_sync_uuid ON recurring_expenses(sync_uuid);
CREATE INDEX idx_time_entries_project ON time_entries(project_id);
CREATE INDEX idx_time_entries_person ON time_entries(person_id);
CREATE INDEX idx_time_entries_stage ON time_entries(stage_id);
CREATE INDEX idx_time_entries_date ON time_entries(date);
CREATE UNIQUE INDEX idx_time_entries_sync_uuid ON time_entries(sync_uuid);
CREATE INDEX idx_clients_archived ON clients(archived_at);
CREATE INDEX idx_projects_archived ON projects(archived_at);
CREATE INDEX idx_contracts_archived ON contracts(archived_at);
CREATE INDEX idx_people_archived ON people(archived_at);
CREATE INDEX idx_assignments_archived ON project_assignments(archived_at);
CREATE INDEX idx_certificates_lifecycle ON payment_certificates(voided_at, archived_at);
CREATE INDEX idx_payments_voided ON payments(voided_at);
CREATE INDEX idx_person_payments_voided ON person_payments(voided_at);
CREATE INDEX idx_expenses_lifecycle ON expenses(voided_at, archived_at);
CREATE UNIQUE INDEX idx_contract_revisions_sync_uuid ON contract_revisions(sync_uuid);
CREATE INDEX idx_contract_revisions_effective ON contract_revisions(contract_id, effective_date, revision_number);
CREATE UNIQUE INDEX idx_variation_orders_sync_uuid ON variation_orders(sync_uuid);
CREATE INDEX idx_variation_orders_contract ON variation_orders(contract_id);
CREATE INDEX idx_certificates_revision ON payment_certificates(contract_revision_id);
CREATE UNIQUE INDEX idx_allocations_payment_certificate_unique
  ON payment_certificate_allocations(payment_id, certificate_id)
  WHERE integrity_exception=0;
CREATE INDEX idx_audit_timestamp ON audit_logs(timestamp DESC);
CREATE INDEX idx_audit_entity ON audit_logs(entity_type,entity_id,timestamp DESC);
CREATE INDEX idx_audit_user ON audit_logs(user_id,timestamp DESC);
CREATE INDEX idx_audit_action ON audit_logs(action,timestamp DESC);
CREATE INDEX idx_backups_type_created ON backups_log(backup_type,created_at DESC,id DESC);
CREATE UNIQUE INDEX idx_quality_open_issue ON data_quality_issues(entity_type,entity_id,field_name,issue_code) WHERE resolved_at IS NULL;
CREATE INDEX idx_documents_project ON documents(project_id,archived_at,added_at);
CREATE UNIQUE INDEX idx_documents_sync_uuid ON documents(sync_uuid);
CREATE UNIQUE INDEX idx_documents_active_hash ON documents(project_id,sha256) WHERE archived_at IS NULL AND sha256 IS NOT NULL;
CREATE UNIQUE INDEX uq_sync_conflict_open ON sync_conflicts(table_name,row_uuid) WHERE status='OPEN';
CREATE INDEX idx_sync_conflict_status ON sync_conflicts(status,detected_at DESC);
CREATE UNIQUE INDEX uq_expenses_number ON expenses(number);

